package com.hrm.service;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.web.server.ResponseStatusException;
@EnabledIfSystemProperty(named="hrm.overtime.sqlserver-tests",matches="true")
class OvertimeSupplementIntegrationTest {
 static OvertimeWorkspaceIntegrationTest t;static OvertimeSupplementService service;
 @BeforeAll static void setup()throws Exception{OvertimeWorkspaceIntegrationTest.setup();t=new OvertimeWorkspaceIntegrationTest();service=OvertimeWorkspaceIntegrationTest.proxy(new OvertimeSupplementService(t.db,t.service,t.core,t.perms,t.clock,3));}
 private long create(){var o=t.service.register(t.hr,t.body(-1,20,21));t.action(t.admin,o.overtimeId(),"approve");return o.overtimeId();}
 private OvertimeSupplementService.Proposal body(long id){return new OvertimeSupplementService.Proposal(t.version(t.hr,id),t.day(-1).atTime(20,0),t.day(-1).atTime(21,0),List.of(),true,"ROLLBACK-ONLY quên chấm công OT");}
 @Test void approvedMissingClockAppearsAndSubmissionKeepsOriginal(){t.rollback(()->{long id=create();assertTrue(service.candidates(t.hr,t.day(-1),t.day(-1),0).items().stream().anyMatch(c->c.row().ot().overtimeId()==id&&c.eligible()));long request=service.submit(t.hr,id,body(id));assertNull(t.service.detail(t.hr,id).row().ot().actualStart());assertEquals("CHO_XU_LY",service.read(t.hr,request).status());assertTrue(service.read(t.admin,request).canDecide());assertFalse(service.read(t.hr,request).canDecide());assertThrows(ResponseStatusException.class,()->service.submit(t.hr,id,body(id)));});}
 @Test void adminApprovalAddsActualButDoesNotConfirm(){t.rollback(()->{long id=create(),request=service.submit(t.hr,id,body(id));service.decide(t.admin,request,true,"Đã đối chiếu bằng chứng");var o=t.service.detail(t.hr,id).row().ot();assertEquals(t.day(-1).atTime(20,0),o.actualStart());assertEquals(t.day(-1).atTime(21,0),o.actualEnd());assertNull(o.confirmedBy());assertEquals("DA_CHAP_NHAN",service.read(t.hr,request).status());assertThrows(ResponseStatusException.class,()->service.decide(t.admin,request,true,"Không mở lại"));});}
 @Test void rejectionKeepsOriginalAndRecordsReason(){t.rollback(()->{long id=create(),request=service.submit(t.hr,id,body(id));service.decide(t.admin,request,false,"Chưa có bằng chứng");assertNull(t.service.detail(t.hr,id).row().ot().actualStart());assertEquals("Chưa có bằng chứng",service.read(t.hr,request).decisionReason());assertEquals("TU_CHOI",service.read(t.hr,request).status());});}
 @Test void onlyOwnerSubmitsAndIndependentAdminDecidesHrRequest(){t.rollback(()->{long id=create();assertThrows(ResponseStatusException.class,()->service.submit(t.employee,id,body(id)));long request=service.submit(t.hr,id,body(id));assertThrows(ResponseStatusException.class,()->service.decide(t.hr,request,true,"Tự duyệt"));assertThrows(ResponseStatusException.class,()->service.read(t.employee,request));assertTrue(service.list(t.hr,true,t.day(-1),t.day(-1),0).items().stream().anyMatch(r->r.requestId()==request));});}
 @Test void threeDayDeadlineAndStaleSnapshotEnforced(){t.rollback(()->{long id=create();var late=OvertimeWorkspaceIntegrationTest.proxy(new OvertimeSupplementService(t.db,t.service,t.core,t.perms,Clock.fixed(t.day(4).atStartOfDay(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant(),ZoneId.of("Asia/Ho_Chi_Minh")),3));assertFalse(late.candidates(t.hr,t.day(-1),t.day(-1),0).items().stream().filter(c->c.row().ot().overtimeId()==id).findFirst().orElseThrow().eligible());assertThrows(ResponseStatusException.class,()->late.submit(t.hr,id,body(id)));long request=service.submit(t.hr,id,body(id));t.db.update("UPDATE dbo.overtime_requests SET reason=reason WHERE overtime_id=?",id);assertThrows(ResponseStatusException.class,()->service.decide(t.admin,request,true,"Dữ liệu đã thay đổi"));assertNull(t.service.detail(t.hr,id).row().ot().actualStart());});}
 @Test void auditFailureRollsBackDecisionAndActualTogether(){t.rollback(()->{long id=create(),request=service.submit(t.hr,id,body(id));var failing=spy(t.db);doThrow(new IllegalStateException("Injected audit failure")).when(failing).update(startsWith("INSERT dbo.audit_logs"),any(Object[].class));var bad=OvertimeWorkspaceIntegrationTest.proxy(new OvertimeSupplementService(failing,t.service,t.core,t.perms,t.clock,3));var nested=new TransactionTemplate(t.manager);nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);assertThrows(IllegalStateException.class,()->nested.executeWithoutResult(status->bad.decide(t.admin,request,true,"Kiểm tra rollback")));assertNull(t.service.detail(t.hr,id).row().ot().actualStart());assertEquals("CHO_XU_LY",service.read(t.admin,request).status());});}
}
